// Fixed Profile Motion Template: cinematic_underline on dm-t-0-trsc
{
  const el = document.getElementById("dm-t-0-trsc");
  if (el) {
    gsap.set(el, { autoAlpha: 0, pointerEvents: "none" });
    tl.set(el, { autoAlpha: 1 }, 1.000);
    const tmTl = gsap.timeline();

tmTl.fromTo(el, { opacity: 0 }, { opacity: 1, duration: 0.1 });
// Starburst flash
const star = el.querySelector(".dm-starburst");
if (star) {
  tmTl.fromTo(star, { scale: 0.2, opacity: 1, transformOrigin: "110px 110px" }, { scale: 1.8, opacity: 0, duration: 0.35, ease: "power2.out" }, 0.05);
}
// Shockwaves ripple outward
tmTl.fromTo(el.querySelector(".dm-wave-1"), { scale: 0.3, opacity: 1, transformOrigin: "110px 110px" }, { scale: 3.2, opacity: 0, duration: 0.85, ease: "power2.out" }, 0.05);
tmTl.fromTo(el.querySelector(".dm-wave-2"), { scale: 0.25, opacity: 1, transformOrigin: "110px 110px" }, { scale: 2.6, opacity: 0, duration: 0.75, ease: "power2.out" }, 0.12);
tmTl.fromTo(el.querySelector(".dm-wave-3"), { scale: 0.2, opacity: 1, transformOrigin: "110px 110px" }, { scale: 2.0, opacity: 0, duration: 0.65, ease: "power2.out" }, 0.18);
// Label arrives on the shockwave tail instead of popping with frame one
const shockLbl = el.querySelector(".dm-shock-label");
if (shockLbl) {
  tmTl.fromTo(shockLbl, { scale: 0.7, opacity: 0, y: 12 }, { scale: 1, opacity: 1, y: 0, duration: 0.35, ease: "back.out(2)" }, 0.22);
}

    tl.add(tmTl, 1.000);
    tl.to(el, { autoAlpha: 0, scale: 0.92, filter: "blur(4px)", duration: 0.45, ease: "power2.in" }, 5.350);
    tl.set(el, { autoAlpha: 0 }, 5.800);
  }
}

