// Fixed Profile Motion Template: sniper_lock on dm-t-54-trsl
{
  const el = document.getElementById("dm-t-54-trsl");
  if (el) {
    gsap.set(el, { autoAlpha: 0, pointerEvents: "none" });
    tl.set(el, { autoAlpha: 1 }, 1.000);
    const tmTl = gsap.timeline();

tmTl.fromTo(el, { opacity: 0 }, { opacity: 1, duration: 0.1 });
// Tactical brackets snap inward violently
const brackets = el.querySelectorAll(".dm-bracket-tmTl, .dm-bracket-tr, .dm-bracket-bl, .dm-bracket-br");
tmTl.fromTo(brackets, { scale: 1.7, opacity: 0, transformOrigin: "130px 130px" }, { scale: 1, opacity: 1, duration: 0.35, ease: "expo.out" }, 0.05);
// Rotating compass dial (single slow sweep sized to the hold, so the timeline completes)
const dial = el.querySelector(".dm-hud-dial");
if (dial) {
  tmTl.to(dial, { rotation: 160, transformOrigin: "130px 130px", duration: 4.4, ease: "none" }, 0);
}
// Label pop
const lbl = el.querySelector(".dm-hud-label");
if (lbl) {
  tmTl.fromTo(lbl, { scale: 0.65, opacity: 0, y: 15 }, { scale: 1, opacity: 1, y: 0, duration: 0.35, ease: "back.out(2)" }, 0.25);
}

    tl.add(tmTl, 1.000);
    tl.to(el, { autoAlpha: 0, scale: 0.92, filter: "blur(4px)", duration: 0.45, ease: "power2.in" }, 5.050);
    tl.set(el, { autoAlpha: 0 }, 5.500);
  }
}

